udre-&#192;-&#201;ternuer-(Objet).html&quot; title=&quot;Poudre &#224; &#233;ternuer&quot;&gt;poudre &#224; &#233;ternuer&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Sacoche-Immobilisante-(Objet).html&quot; title=&quot;Sacoche immobilisante&quot;&gt;sacoche immobilisante&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;S&#232;che-Colle-Alchimique-(Objet).html&quot; title=&quot;S&#232;che-colle alchimique&quot;&gt;s&#232;che-colle alchimique&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Sels-Odorants-(Objet).html&quot; title=&quot;Sels odorants&quot;&gt;sels odorants&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Tic-Tonique-(Objet).html&quot; title=&quot;Tic tonique&quot;&gt;tic tonique&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Objets ordinaires.&lt;/b&gt; Horloges ou autres objets complexes.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Pi&#232;ges.&lt;/b&gt; Tous les &lt;a class=&quot;pagelink&quot; href=&quot;Exemples-De-Pi&#232;ges.html&quot; title=&quot;Exemples de pi&#232;ges&quot;&gt;pi&#232;ges&lt;/a&gt; avec un FP entre 6 et 10.&lt;/li&gt;&lt;li&gt;&lt;b&gt;V&#233;hicules.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Bateau-&#192;-Voiles-(Objet).html&quot; title=&quot;Bateau &#224; voiles&quot;&gt;Bateau &#224; voiles&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Bateau-De-Guerre-(Objet).html&quot; title=&quot;Bateau de guerre&quot;&gt;bateau de guerre&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Gal&#232;re-(Objet).html&quot; title=&quot;Gal&#232;re&quot;&gt;gal&#232;re&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;h4 class=&quot;separator&quot;&gt;Tr&#232;s complexe (DD 30)&lt;a class=&quot;headeranchor&quot; id=&quot;Tr&#232;s_complexe_DD_DA_5&quot; href=&quot;#Tr&#232;s_complexe_DD_DA_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h4&gt;&lt;ul&gt;&lt;li&gt;&lt;b&gt;Armes.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Engins-De-Si&#232;ge.html&quot; title=&quot;Tableau r&#233;capitulatif des engins de si&#232;ge&quot;&gt;Engins de si&#232;ge alchimiques&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Engins-De-Si&#232;ge.html&quot; title=&quot;Tableau r&#233;capitulatif des engins de si&#232;ge&quot;&gt;engins de si&#232;ge &#224; feu&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Objets alchimiques.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Feu-Dartifice-Ballerine-Banshie-(Objet).html&quot; title=&quot;Feu d&amp;#39;artifice (ballerine banshie)&quot;&gt;feu d’artifice (ballerine banshie)&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;&#201;nergisant-Spirituel-(Objet).html&quot; title=&quot;&#201;nergisant spirituel&quot;&gt;&#233;nergisant spirituel&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Feu-Dartifice-Fontaine-De-Flammes-(Objet).html&quot; title=&quot;Feu d&amp;#39;artifice (fontaine de flammes)&quot;&gt;feu d&#39;artifice (fontaines de flammes)&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Huile-De-Troll-(Objet).html&quot; title=&quot;Huile de troll&quot;&gt;huile de troll&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Poudre-Oxydante-(Objet).html&quot; title=&quot;Poudre oxydante&quot;&gt;poudre oxydante&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Sacoche-Immobilisante-De-Feu-(Objet).html&quot; title=&quot;Sacoche immobilisante de feu&quot;&gt;sacoche immobilisante de feu&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Pi&#232;ges.&lt;/b&gt; Tous les &lt;a class=&quot;pagelink&quot; href=&quot;Exemples-De-Pi&#232;ges.html&quot; title=&quot;Exemples de pi&#232;ges&quot;&gt;pi&#232;ges&lt;/a&gt; avec un FP entre 11 et 15.&lt;/li&gt;&lt;li&gt;&lt;b&gt;V&#233;hicules.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;V&#233;hicules-A&#233;riens-(V&#233;hicules).html#DIRIGEABLE&quot; title=&quot;Les v&#233;hicules a&#233;riens&quot;&gt;Dirigeable&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;h4 class=&quot;separator&quot;&gt;Extr&#234;mement complexe (DD 35)&lt;a class=&quot;headeranchor&quot; id=&quot;Extr&#234;mement_complexe_DD_DF_6&quot; href=&quot;#Extr&#234;mement_complexe_DD_DF_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h4&gt;&lt;ul&gt;&lt;li&gt;&lt;b&gt;Pi&#232;ges.&lt;/b&gt; Tous les &lt;a class=&quot;pagelink&quot; href=&quot;Exemples-De-Pi&#232;ges.html&quot; title=&quot;Exemples de pi&#232;ges&quot;&gt;pi&#232;ges&lt;/a&gt; avec un FP de 16 ou plus.&lt;/li&gt;&lt;li&gt;&lt;b&gt;V&#233;hicules.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;V&#233;hicules-A&#233;riens-(V&#233;hicules).html#DRAGONALCHIMIQUE&quot; title=&quot;Les v&#233;hicules a&#233;riens&quot;&gt;Dragon alchimique&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;V&#233;hicules-Terrestres-(V&#233;hicules).html#GEANTDEVAPEUR&quot; title=&quot;Les v&#233;hicules terrestres&quot;&gt;g&#233;ant de vapeur&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Gestion des assistants&lt;a class=&quot;headeranchor&quot; id=&quot;Gestion_des_assistants_9&quot; href=&quot;#Gestion_des_assistants_9&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;div style=&quot;float:right; background-color: #fff; padding: 0 0 4px 8px&quot;&gt;
&lt;div style=&quot;border: 1px solid #4b3124; padding: 4px&quot;&gt;
&lt;center&gt;
&lt;table CLASS=&quot;tablo autoalt&quot;&gt;&lt;caption&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;OUVRIERSQUALIFIES&quot; href=&quot;#OUVRIERSQUALIFIES&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;Ouvriers qualifi&#233;s&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Rangs en&lt;br /&gt;Artisanat&lt;/td&gt;&lt;td&gt;Bonus en&lt;br /&gt;Artisanat&lt;/td&gt;&lt;td&gt;R&#233;mun&#233;ration&lt;br /&gt;par jour&lt;/td&gt;&lt;td&gt;R&#233;mun&#233;ration&lt;br /&gt;par semaine&lt;/td&gt;&lt;td&gt;Taille de la&lt;br /&gt;communaut&#233;&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;1&lt;/td&gt;&lt;td&gt;+4&lt;/td&gt;&lt;td&gt;3 pa&lt;/td&gt;&lt;td&gt;2 po, 1 pa&lt;/td&gt;&lt;td&gt;Hameau&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;2&lt;/td&gt;&lt;td&gt;+5&lt;/td&gt;&lt;td&gt;4 pa&lt;/td&gt;&lt;td&gt;2 po, 8 pa&lt;/td&gt;&lt;td&gt;Village&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;3&lt;/td&gt;&lt;td&gt;+6&lt;/td&gt;&lt;td&gt;6 pa&lt;/td&gt;&lt;td&gt;4 po, 2 pa&lt;/td&gt;&lt;td&gt;Petite bourgade&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;4&lt;/td&gt;&lt;td&gt;+7&lt;/td&gt;&lt;td&gt;8 pa&lt;/td&gt;&lt;td&gt;5 po, 6 pa&lt;/td&gt;&lt;td&gt;Grosse bourgade&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;5&lt;/td&gt;&lt;td&gt;+8&lt;/td&gt;&lt;td&gt;1 po&lt;/td&gt;&lt;td&gt;7 po&lt;/td&gt;&lt;td&gt;Petite ville&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;+9&lt;/td&gt;&lt;td&gt;1 po, 5 pa&lt;/td&gt;&lt;td&gt;10 po, 5 pa&lt;/td&gt;&lt;td&gt;Grande ville&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;7&lt;/td&gt;&lt;td&gt;+10&lt;/td&gt;&lt;td&gt;2 po&lt;/td&gt;&lt;td&gt;14 po&lt;/td&gt;&lt;td&gt;M&#233;tropole&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/center&gt;&lt;/div&gt;&lt;/div&gt;Comme indiqu&#233; dans les deux versions de la comp&#233;tence, l’Artisanat permet aux personnages de superviser des ouvriers non-qualifi&#233;s. Un ouvrier non-qualifi&#233; ne poss&#232;de aucun rang en Artisanat mais il peut aider au processus de fabrication des objets avec la comp&#233;tence d’Artisanat. Il faut avant tout le r&#233;mun&#233;rer en lui versant 1 pa par jour ou 7 pa pour une semaine de travail. Chaque ouvrier non-qualifi&#233; embauch&#233; peut effectuer l’action aider quelqu’un avec un bonus de +0 (on part du principe qu’il poss&#232;de une valeur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; de 10 ou 11 et qu’il ne poss&#232;de aucun rang dans la comp&#233;tence d’Artisanat appropri&#233;e) lors du test d’Artisanat du personnage. En r&#232;gle g&#233;n&#233;rale, le personnage peut embaucher un maximum de deux artisans pour l’aider &#224; la fabrication de la plupart des objets de petite taille ou relativement simples (tels que le mat&#233;riel d’aventurier, les objets alchimiques, les armures, les poisons et les armes). S’il souhaite fabriquer des objets imposants ou complexes (tels que des engins de si&#232;ge ou des v&#233;hicules), le personnage peut embaucher jusqu’&#224; dix ouvriers non-qualifi&#233;s comme assistants.&lt;br /&gt;&lt;br /&gt;Si le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Maitredujeu.html&quot; title=&quot;MJ&quot;&gt;MJ&lt;/a&gt; l’y autorise, le personnage peut &#233;galement embaucher et superviser des ouvriers qualifi&#233;s. Ces ouvriers poss&#232;dent des rangs dans la comp&#233;tence d’Artisanat appropri&#233;e et apportent donc une aide plus int&#233;ressante lors du processus de fabrication. La table &quot;&lt;a class=&quot;pagelink&quot; href=&quot;Artisanat-Unchained.html#OUVRIERSQUALIFIES&quot; title=&quot;R&#232;gles alternatives sur l&amp;#39;artisanat&quot;&gt;Ouvriers qualifi&#233;s&lt;/a&gt;&quot; fournit les informations sur ce type d’individus, le montant de leur r&#233;mun&#233;ration, le nombre de rangs qu’ils poss&#232;dent dans la comp&#233;tence d’Artisanat appropri&#233;e, leur bonus aux tests d’Artisanat et la taille moyenne des communaut&#233;s o&#249; on peut les trouver. Le personnage peut uniquement embaucher des ouvriers qualifi&#233;s qui poss&#232;dent moins de rangs dans la comp&#233;tence d’Artisanat appropri&#233;e que lui. En effet, un ouvrier plus qualifi&#233; n’acceptera pas le statut de simple assistant.&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Espace de travail&lt;a class=&quot;headeranchor&quot; id=&quot;Espace_de_travail_10&quot; href=&quot;#Espace_de_travail_10&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Quand un personnage souhaite fabriquer des objets, il doit disposer d’outils et d’un espace de travail appropri&#233;s. Ce qui constitue un espace de travail appropri&#233; d&#233;pend souvent des situations. La r&#233;paration d’armes et d’armures sur le terrain ne requiert qu’un endroit calme et d&#233;gag&#233; alors qu’un personnage qui souhaite fabriquer un harnois doit disposer d’un atelier et d’une forge. En r&#232;gle g&#233;n&#233;rale, les objets dot&#233;s d’une difficult&#233; de fabrication normale ou sup&#233;rieure n&#233;cessitent un atelier adapt&#233; mais, dans certaines circonstances, le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Maitredujeu.html&quot; title=&quot;MJ&quot;&gt;MJ&lt;/a&gt; peut d&#233;cider que le personnage peut les fabriquer sur le terrain. Les objets alchimiques et les poisons constituent des exceptions car leur petite taille facilite leur fabrication sur le terrain, surtout si l’on dispose d’un &lt;a class=&quot;pagelink&quot; href=&quot;Laboratoire-Dalchimiste-(Objet).html&quot; title=&quot;Laboratoire d&amp;#39;alchimiste&quot;&gt;laboratoire d’alchimiste&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Espaces de travail de ma&#238;tre-artisan.&lt;/b&gt; Ces espaces de travail spacieux et convenablement approvisionn&#233;s facilitent la fabrication des objets, surtout si le personnage embauche des ouvriers qualifi&#233;s et non-qualifi&#233;s. Ces espaces de travail de ma&#238;tre-artisan conf&#232;rent &#224; ces deux types d’ouvriers un bonus de circonstances de +2 aux tests pour aider quelqu’un, afin d’am&#233;liorer les chances de r&#233;ussite du personnage. De plus, si un ouvrier qualifi&#233; ou non-qualifi&#233; r&#233;ussit de 5 points ou plus son test pour aider quelqu’un, il conf&#232;re au personnage un bonus de +3 &#224; son test au lieu du bonus habituel de +2. La location d’un espace de travail de ma&#238;tre-artisan adapt&#233; &#224; la fabrication d’objets de taille relativement r&#233;duite (tels que du mat&#233;riel d’aventurier, des objets alchimiques, des armures, des poisons et des armes) s’&#233;l&#232;ve g&#233;n&#233;ralement &#224; 5 po par jour. Pour un espace de travail de ma&#238;tre-artisan adapt&#233; &#224; la fabrication d’objets plus imposants (tels que des engins de si&#232;ge et des v&#233;hicules), il faut compter 20 po par jour.&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Mati&#232;res premi&#232;res sp&#233;ciales&lt;a class=&quot;headeranchor&quot; id=&quot;Mati&#232;res_premi&#232;res_sp&#233;ciales_11&quot; href=&quot;#Mati&#232;res_premi&#232;res_sp&#233;ciales_11&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Pour fabriquer un objet, il faut tout d’abord se procurer des mati&#232;res premi&#232;res, sans lesquelles le travail ne peut commencer. Ces mati&#232;res premi&#232;res sont g&#233;n&#233;ralement des produits divers que l’on peut acheter et qui sont indispensables pour fabriquer un objet. Par exemple, il faut de l’acier pour une valeur de 37 po et 5 pa (en partant du principe que vous utilisez la version alternative de la comp&#233;tence d’Artisanat d&#233;crite ci-dessus) pour commencer la confection d’une cotte de mailles. Toutes les mati&#232;res premi&#232;res ne se valent pas et certaines sont plus adapt&#233;es &#224; l’artisanat : ce sont les mati&#232;res premi&#232;res sp&#233;ciales.&lt;br /&gt;&lt;br /&gt;&#192; la diff&#233;rence des mat&#233;riaux ordinaires, les mati&#232;res premi&#232;res sp&#233;ciales ont &#224; la fois un prix et un co&#251;t de fabrication. Le prix d’une mati&#232;re premi&#232;re sp&#233;ciale correspond &#224; son prix d’achat ou de vente. Les mati&#232;res premi&#232;res sp&#233;ciales sont des produits de consommation et, comme l’ensemble des autres produits de ce type, on peut les acheter ou les vendre au m&#234;me prix. Le co&#251;t de fabrication est la somme en or que l’on doit verser pour travailler une mati&#232;re donn&#233;e. Par exemple, le prix de 500 grammes d’acier de qualit&#233; sup&#233;rieure s’&#233;l&#232;ve &#224; 8 po mais son co&#251;t de fabrication s’&#233;l&#232;ve &#224; 4 po les 500 grammes. On peut acheter ou vendre 500 grammes de cet acier pour 8 po mais, s’il est destin&#233; &#224; servir de mati&#232;re premi&#232;re pour fabriquer des objets, on consid&#232;re que ces 500 grammes valent 4 po.&lt;br /&gt;&lt;br /&gt;M&#234;me si l’on peut acheter et vendre des mati&#232;res premi&#232;res sp&#233;ciales, il est tout de m&#234;me pr&#233;f&#233;rable d’en faire des tr&#233;sors que les personnages auront l’occasion de d&#233;couvrir. En tant que &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Maitredujeu.html&quot; title=&quot;MJ&quot;&gt;MJ&lt;/a&gt;, si l’un des PJ de votre groupe a investi des rangs dans une comp&#233;tence d’Artisanat, songez &#224; remplacer de temps en temps certains tr&#233;sors mon&#233;taires par ces biens de consommation sp&#233;ciaux.&lt;br /&gt;&lt;br /&gt;Le co&#251;t de fabrication des mati&#232;res premi&#232;res sp&#233;ciales est toujours deux fois moins &#233;lev&#233; que leur prix r&#233;el. Elles sont &#233;galement dot&#233;es de caract&#233;ristiques sp&#233;ciales quand on les utilise pour fabriquer des objets en appliquant les r&#232;gles de la comp&#233;tence d’Artisanat alternative d&#233;crite plus haut. Une mati&#232;re premi&#232;re sp&#233;ciale ne peut poss&#233;der plus d’une caract&#233;ristique sp&#233;ciale parmi celles d&#233;crites ci-dessous.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Mati&#232;res premi&#232;res faciles &#224; travailler.&lt;/b&gt; Ce type de mati&#232;res premi&#232;res permet de fabriquer des objets plus facilement et plus rapidement. Quand on les utilise, la valeur de progression quotidienne de l’objet est doubl&#233;e. Par exemple, si un personnage fabrique une &lt;a class=&quot;pagelink&quot; href=&quot;Cotte-De-Mailles-(Armure).html&quot; title=&quot;Cotte de mailles&quot;&gt;cotte de mailles&lt;/a&gt; en utilisant de l’acier facile &#224; travailler, sa valeur de progression quotidienne s’&#233;l&#232;ve &#224; 4 po au lieu de 2 po.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Mati&#232;res premi&#232;res de qualit&#233; sup&#233;rieure.&lt;/b&gt; La qualit&#233; de ces mati&#232;res est telle qu’on peut les utiliser pour cr&#233;er avec aisance des objets d’excellente qualit&#233;. Quand on utilise des mati&#232;res premi&#232;res de qualit&#233; sup&#233;rieure pour cr&#233;er des objets de ma&#238;tre ou compos&#233;s de mat&#233;riaux sp&#233;ciaux, la difficult&#233; de fabrication n’augmente pas. Par exemple, si un personnage fabrique une &lt;a class=&quot;pagelink&quot; href=&quot;Cotte-De-Mailles-(Armure).html&quot; title=&quot;Cotte de mailles&quot;&gt;cotte de mailles&lt;/a&gt; de ma&#238;tre en utilisant de l’acier de qualit&#233; sup&#233;rieure, la difficult&#233; du test reste normale (&lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 15) au lieu de devenir difficile (&lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 20).&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Mati&#232;res premi&#232;res mall&#233;ables.&lt;/b&gt; Ce type de mati&#232;res premi&#232;res sp&#233;ciales r&#233;siste mieux aux erreurs de manipulation que les mati&#232;res similaires normales. Si un personnage rate un test d’Artisanat de 5 points ou plus quand il utilise des mati&#232;res premi&#232;res mall&#233;ables, il ne perd pas le montant de mati&#232;res premi&#232;res &#233;quivalent &#224; la valeur de progression quotidienne de l’objet.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Mati&#232;res premi&#232;res pures.&lt;/b&gt; Ces mati&#232;res premi&#232;res facilitent le processus de fabrication des objets. Quand un personnage utilise ce type de mati&#232;res premi&#232;res, il effectue deux tests d’Artisanat et conserve le meilleur r&#233;sultat.&lt;br /&gt;&lt;br /&gt;&lt;table CLASS=&quot;tablo centre autoalt&quot; WIDTH=&quot;100%&quot;&gt;&lt;caption&gt;Prix des mati&#232;res premi&#232;res sp&#233;ciales&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Mati&#232;res premi&#232;res sp&#233;ciales (500 g)&lt;/td&gt;&lt;td&gt;Faciles &#224; travailler&lt;/td&gt;&lt;td&gt;Qualit&#233; sup&#233;rieure&lt;/td&gt;&lt;td&gt;Mall&#233;ables&lt;/td&gt;&lt;td&gt;Pures&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;Acier&lt;/td&gt;&lt;td&gt;8 po&lt;/td&gt;&lt;td&gt;8 po&lt;/td&gt;&lt;td&gt;5 po&lt;/td&gt;&lt;td&gt;6 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux#Acierardent.html&quot; title=&quot;Acier ardent&quot;&gt;Acier ardent&lt;/a&gt;&lt;/td&gt;&lt;td&gt;300 po&lt;/td&gt;&lt;td&gt;300 po&lt;/td&gt;&lt;td&gt;187 po, 5 pa&lt;/td&gt;&lt;td&gt;225 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux#Acierglac&#233;.html&quot; title=&quot;Acier glac&#233;&quot;&gt;Acier glac&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;300 po&lt;/td&gt;&lt;td&gt;300 po&lt;/td&gt;&lt;td&gt;187 po, 5 pa&lt;/td&gt;&lt;td&gt;225 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux#Aciervivant.html&quot; title=&quot;Acier vivant&quot;&gt;Acier vivant&lt;/a&gt;&lt;/td&gt;&lt;td&gt;200 po&lt;/td&gt;&lt;td&gt;200 po&lt;/td&gt;&lt;td&gt;125 po&lt;/td&gt;&lt;td&gt;150 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux#Adamantium.html&quot; title=&quot;adamantium&quot;&gt;Adamantium&lt;/a&gt;&lt;/td&gt;&lt;td&gt;600 po&lt;/td&gt;&lt;td&gt;600 po&lt;/td&gt;&lt;td&gt;375 po&lt;/td&gt;&lt;td&gt;450 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux#Argent.html&quot; title=&quot;argent alchimique&quot;&gt;Argent alchimique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;20 po&lt;/td&gt;&lt;td&gt;20 po&lt;/td&gt;&lt;td&gt;12 po, 5 pa&lt;/td&gt;&lt;td&gt;15 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Bois&lt;/td&gt;&lt;td&gt;2 po&lt;/td&gt;&lt;td&gt;2 po&lt;/td&gt;&lt;td&gt;1 po, 2 pa, 5 pc&lt;/td&gt;&lt;td&gt;1 po, 5 pa&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux#Boisflexible.html&quot; title=&quot;Bois flexible&quot;&gt;Bois flexible&lt;/a&gt;&lt;/td&gt;&lt;td&gt;300 po&lt;/td&gt;&lt;td&gt;300 po&lt;/td&gt;&lt;td&gt;187 po, 5 pa&lt;/td&gt;&lt;td&gt;225 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux#Boisvert.html&quot; title=&quot;bois vert&quot;&gt;Bois vert&lt;/a&gt;&lt;/td&gt;&lt;td&gt;100 po&lt;/td&gt;&lt;td&gt;100 po&lt;/td&gt;&lt;td&gt;62 po, 5 pa&lt;/td&gt;&lt;td&gt;75 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Armes-Et-Armures-Primitives.html#Bronze_0&quot; title=&quot;Armes et armures primitives&quot;&gt;Bronze&lt;/a&gt;&lt;/td&gt;&lt;td&gt;10 po&lt;/td&gt;&lt;td&gt;10 po&lt;/td&gt;&lt;td&gt;6 po, 2 pa, 5 pc&lt;/td&gt;&lt;td&gt;7 po, 5 pa&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux#Bronze&#233;lys&#233;en.html&quot; title=&quot;Bronze &#233;lys&#233;en&quot;&gt;Bronze &#233;lys&#233;en&lt;/a&gt;&lt;/td&gt;&lt;td&gt;400 po&lt;/td&gt;&lt;td&gt;400 po&lt;/td&gt;&lt;td&gt;250 po&lt;/td&gt;&lt;td&gt;300 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux#Crindegriffon.html&quot; title=&quot;Crin de griffon&quot;&gt;Crin de griffon&lt;/a&gt;&lt;/td&gt;&lt;td&gt;80 po&lt;/td&gt;&lt;td&gt;80 po&lt;/td&gt;&lt;td&gt;50 po&lt;/td&gt;&lt;td&gt;60 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux#Cristaldesang.html&quot; title=&quot;Cristal de sang&quot;&gt;Cristal de sang&lt;/a&gt;&lt;/td&gt;&lt;td&gt;80 po&lt;/td&gt;&lt;td&gt;80 po&lt;/td&gt;&lt;td&gt;50 po&lt;/td&gt;&lt;td&gt;60 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Cuir&lt;/td&gt;&lt;td&gt;6 po&lt;/td&gt;&lt;td&gt;6 po&lt;/td&gt;&lt;td&gt;3 po, 7 pa, 5 pc&lt;/td&gt;&lt;td&gt;4 po, 5 pa&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux#Ebenite.html&quot; title=&quot;&#233;b&#233;nite&quot;&gt;&#201;b&#233;nite&lt;/a&gt;&lt;/td&gt;&lt;td&gt;20 po&lt;/td&gt;&lt;td&gt;20 po&lt;/td&gt;&lt;td&gt;12 po, 5pa&lt;/td&gt;&lt;td&gt;15 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux#Ferfroid.html&quot; title=&quot;fer froid&quot;&gt;Fer froid&lt;/a&gt;&lt;/td&gt;&lt;td&gt;100 po&lt;/td&gt;&lt;td&gt;100 po&lt;/td&gt;&lt;td&gt;62 po, 5 pa&lt;/td&gt;&lt;td&gt;75 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux#Mithral.html&quot; title=&quot;mithral&quot;&gt;Mithral&lt;/a&gt;&lt;/td&gt;&lt;td&gt;800 po&lt;/td&gt;&lt;td&gt;800 po&lt;/td&gt;&lt;td&gt;500 po&lt;/td&gt;&lt;td&gt;600 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Armes-Et-Armures-Primitives.html#Obsidienne_1&quot; title=&quot;Armes et armures primitives&quot;&gt;Obsidienne&lt;/a&gt;&lt;/td&gt;&lt;td&gt;6 po&lt;/td&gt;&lt;td&gt;6 po&lt;/td&gt;&lt;td&gt;3 po, 7 pa, 5 pc&lt;/td&gt;&lt;td&gt;4 po, 5 pa&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Armes-Et-Armures-Primitives.html#Or_2&quot; title=&quot;Armes et armures primitives&quot;&gt;Or&lt;/a&gt;&lt;/td&gt;&lt;td&gt;100 po&lt;/td&gt;&lt;td&gt;100 po&lt;/td&gt;&lt;td&gt;62 po, 5 pa&lt;/td&gt;&lt;td&gt;75 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Armes-Et-Armures-Primitives.html#Os_3&quot; title=&quot;Armes et armures primitives&quot;&gt;Os&lt;/a&gt;&lt;/td&gt;&lt;td&gt;2 po&lt;/td&gt;&lt;td&gt;2 po&lt;/td&gt;&lt;td&gt;1 po, 2 pa, 5 pc&lt;/td&gt;&lt;td&gt;1 po, 5 pa&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux#Peaudange.html&quot; title=&quot;Peau d&amp;#39;ange&quot;&gt;Peau d’ange&lt;/a&gt;&lt;/td&gt;&lt;td&gt;200 po&lt;/td&gt;&lt;td&gt;200 po&lt;/td&gt;&lt;td&gt;125 po&lt;/td&gt;&lt;td&gt;150 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux#Peaudanguille.html&quot; title=&quot;Peau d&amp;#39;anguille&quot;&gt;Peau d’anguille&lt;/a&gt;&lt;/td&gt;&lt;td&gt;250 po&lt;/td&gt;&lt;td&gt;250 po&lt;/td&gt;&lt;td&gt;156 po, 2 pa, 5 pc&lt;/td&gt;&lt;td&gt;187 po, 5 pa&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux#Peaudedragon.html&quot; title=&quot;Peau de dragon&quot;&gt;Peau de dragon&lt;/a&gt;&lt;/td&gt;&lt;td&gt;100 po&lt;/td&gt;&lt;td&gt;100 po&lt;/td&gt;&lt;td&gt;62 po, 5 pa&lt;/td&gt;&lt;td&gt;75 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Armes-Et-Armures-Primitives.html#Pierre_4&quot; title=&quot;Armes et armures primitives&quot;&gt;Pierre&lt;/a&gt;&lt;/td&gt;&lt;td&gt;6 po&lt;/td&gt;&lt;td&gt;6 po&lt;/td&gt;&lt;td&gt;3 po, 7 pa, 5 pc&lt;/td&gt;&lt;td&gt;4 po, 5 pa&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux#Racinedewy.html&quot; title=&quot;Racine de wy&quot;&gt;Racine de wy&lt;/a&gt;&lt;/td&gt;&lt;td&gt;400 po&lt;/td&gt;&lt;td&gt;400 po&lt;/td&gt;&lt;td&gt;250 po&lt;/td&gt;&lt;td&gt;300 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Tissu&lt;/td&gt;&lt;td&gt;8 po&lt;/td&gt;&lt;td&gt;8 po&lt;/td&gt;&lt;td&gt;5 po&lt;/td&gt;&lt;td&gt;6 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux#Tissudesombrefeuille.html&quot; title=&quot;Tissu de sombrefeuille&quot;&gt;Tissu de sombrefeuille&lt;/a&gt;&lt;/td&gt;&lt;td&gt;20 po&lt;/td&gt;&lt;td&gt;20 po&lt;/td&gt;&lt;td&gt;12 po, 5 pa&lt;/td&gt;&lt;td&gt;15 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux#Viridium.html&quot; title=&quot;Viridium&quot;&gt;Viridium&lt;/a&gt;&lt;/td&gt;&lt;td&gt;400 po&lt;/td&gt;&lt;td&gt;400 po&lt;/td&gt;&lt;td&gt;250 po&lt;/td&gt;&lt;td&gt;300 po&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
